@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Mono:wght@400;500&family=Inter:wght@400;500;600;700;800&display=swap');
:root{--ink:#101619;--panel:#172024;--muted:#91a09c;--paper:#e9e9dc;--orange:#e87942;--lime:#c0d26c;--line:rgba(222,232,218,.15)}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#0d1214;color:var(--paper);font-family:Inter,Arial,sans-serif;display:grid;place-items:center;padding:22px;background-image:radial-gradient(ellipse at 50% 20%,#263033 0,#111719 48%,#0d1214 100%);overflow-x:hidden}.game-shell{width:min(1120px,100%);}.topbar{height:60px;display:flex;align-items:center;justify-content:space-between;padding:0 12px 14px}.brand{display:flex;gap:11px;align-items:center}.brand-mark{width:34px;height:34px;border:1px solid #53605e;border-radius:50%;display:grid;place-items:center;color:var(--orange);font-size:23px}.brand b{font:800 17px 'Barlow Condensed',sans-serif;letter-spacing:1.5px;display:block}.brand small{font:9px 'DM Mono',monospace;letter-spacing:1.4px;color:#85918d}.header-right{display:flex;align-items:center;gap:22px}.status-pill,.chapter-label{font:10px 'DM Mono',monospace;letter-spacing:1px;color:#aab5ac}.status-pill{display:flex;align-items:center;gap:8px}.status-pill i{width:6px;height:6px;background:#a5c86d;border-radius:50%;box-shadow:0 0 10px #a5c86d}.chapter-label{border-left:1px solid var(--line);padding-left:22px;color:var(--orange)}.game-frame{width:100%;aspect-ratio:16/9;position:relative;background:#172024;overflow:hidden;border:1px solid #3a4745;box-shadow:0 22px 80px #0009;border-radius:3px;touch-action:none}canvas{width:100%;height:100%;display:block}.screen-shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,13,15,.9),rgba(8,13,15,.59) 51%,rgba(8,13,15,.12));pointer-events:none;transition:opacity .4s}.panel-screen{position:absolute;z-index:3;left:8%;top:50%;transform:translateY(-50%);width:min(510px,80%);padding:20px 24px}.hidden{display:none!important}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:1.3px;color:#c5d0c4}.eyebrow span{color:var(--orange);padding:0 7px}.eyebrow b{color:var(--orange);font-weight:500}.title-screen{left:7.5%;top:48%;}.title-screen h1{font:900 clamp(45px,7vw,80px)/.8 'Barlow Condensed',Impact,sans-serif;letter-spacing:1px;margin:21px 0 16px;color:#f0eee3;text-shadow:0 3px 22px #0008}.title-screen h1 span{color:var(--orange)}.title-screen h1 em{font-style:normal;color:var(--orange);font-size:.77em;letter-spacing:3.3px}.title-screen p,.briefing p,.recruit-screen p,.game-over p,.victory p{max-width:380px;color:#c1c6b8;font-size:13px;line-height:1.7;margin:0 0 25px}.title-bottom{display:flex;align-items:center;gap:18px}.primary-btn{background:var(--orange);border:0;color:#141816;min-height:43px;padding:0 19px;font:800 12px 'Barlow Condensed',sans-serif;letter-spacing:1.1px;cursor:pointer;transition:transform .15s,background .15s;box-shadow:4px 4px 0 #853d25}.primary-btn span{padding-left:18px;font-size:17px;vertical-align:-1px}.primary-btn:hover{background:#ff9860;transform:translateY(-2px)}.primary-btn:active{transform:translate(1px,2px);box-shadow:2px 2px 0 #853d25}.save-note{font:9px 'DM Mono',monospace;color:#96a49b;letter-spacing:.5px}.title-stamp{position:absolute;right:-340px;top:15px;width:78px;height:78px;border:2px solid #bc6542;color:#de8c69;display:grid;place-items:center;text-align:center;transform:rotate(12deg);font:800 10px/1.1 'DM Mono',monospace;letter-spacing:1px;opacity:.8}.briefing,.recruit-screen,.game-over,.victory{left:50%;top:50%;transform:translate(-50%,-50%);width:min(620px,90%);background:rgba(17,25,27,.93);border:1px solid #63706b;box-shadow:0 15px 70px #000c;padding:28px 34px}.briefing h2,.recruit-screen h2,.game-over h2,.victory h2{font:800 clamp(30px,5vw,47px)/.95 'Barlow Condensed',sans-serif;letter-spacing:.5px;margin:14px 0 12px}.briefing p,.recruit-screen p,.game-over p,.victory p{max-width:490px;font-size:12px;margin-bottom:20px}.brief-stats{display:flex;gap:0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin:18px 0 22px;padding:13px 0}.brief-stats span{flex:1;border-right:1px solid var(--line);padding-left:14px}.brief-stats span:first-child{padding-left:0}.brief-stats span:last-child{border:0}.brief-stats small{display:block;color:#87968e;font:9px 'DM Mono',monospace;letter-spacing:.8px;margin-bottom:7px}.brief-stats b{font:700 12px 'Barlow Condensed',sans-serif;letter-spacing:.6px;color:#e3e5d8}.brief-stats span:first-child b{color:var(--lime)}.recruit-screen{text-align:center}.recruit-screen .eyebrow{color:var(--lime)}.recruit-screen p{margin:0 auto 16px}.recruit-card{width:min(360px,100%);margin:16px auto 20px;text-align:left;background:#202b2b;border:1px solid #728271;padding:15px;display:flex;align-items:center;gap:15px}.recruit-avatar{width:68px;height:68px;background:#3a4540;border:1px solid #74806b;display:grid;place-items:center;font-size:33px;flex-shrink:0}.recruit-card h3{font:800 21px 'Barlow Condensed',sans-serif;margin:0 0 5px}.recruit-card p{font-size:10px!important;margin:0!important;color:#aab7a8;line-height:1.45}.recruit-card .tag{font:9px 'DM Mono',monospace;color:var(--lime);letter-spacing:1px;margin-bottom:5px}.quiet-btn{display:block;margin:13px auto 0;background:none;color:#9da99e;border:0;text-decoration:underline;font:10px 'DM Mono',monospace;cursor:pointer}.game-over,.victory{text-align:center}.game-over .primary-btn,.victory .primary-btn{margin:8px}.hud{position:absolute;inset:0;z-index:2;pointer-events:none}.hud button,.deploy-card{pointer-events:auto}.mission-hud{position:absolute;top:17px;left:18px;display:flex;align-items:center;gap:9px;background:#111a1ce8;padding:7px 12px 7px 8px;border:1px solid #78827855}.mission-icon{width:28px;height:28px;display:grid;place-items:center;background:#bd6942;color:#161b19;font-size:20px}.mission-hud small,.mission-hud b{display:block;font:9px 'DM Mono',monospace;letter-spacing:.5px}.mission-hud small{color:#a7b3a5;margin-bottom:3px}.mission-hud b{font:700 13px 'Barlow Condensed',sans-serif;letter-spacing:.7px}.route-track{position:absolute;top:21px;left:50%;transform:translateX(-50%);width:25%;max-width:240px}.route-track-label,.health-title{display:flex;justify-content:space-between;font:9px 'DM Mono',monospace;color:#d4d8c8;letter-spacing:.6px;margin-bottom:5px}.route-track-label b{color:var(--lime)}.track,.health-track{height:4px;background:#454b43}.track i,.health-track i{height:100%;display:block;width:0;background:var(--lime);transition:width .25s}.pause-btn{position:absolute;right:17px;top:16px;width:32px;height:32px;background:#111a1ce8;color:#e9e9dc;border:1px solid #aeb8a555;cursor:pointer;font-size:14px}.pause-pop{position:absolute;right:18px;top:56px;background:#121b1c;border:1px solid #829087;padding:13px;width:170px;pointer-events:auto;box-shadow:0 8px 20px #0008}.pause-pop b,.pause-pop span{display:block;font:10px 'DM Mono',monospace;margin-bottom:6px}.pause-pop span{color:#a9b5aa}.pause-pop button{background:var(--orange);border:0;width:100%;padding:7px;font:800 11px 'Barlow Condensed',sans-serif;cursor:pointer}.carrier-health{position:absolute;top:73px;right:18px;width:150px;padding:7px 9px;background:#111a1ce8;border:1px solid #77847a44}.health-title{font-size:8px;margin:0 0 5px}.health-title b{color:var(--lime)}.health-track{height:5px}.health-track i{background:var(--lime)}.credits{position:absolute;left:19px;bottom:107px;color:var(--lime);font:17px 'DM Mono',monospace;background:#111a1ce8;border:1px solid #77847a44;padding:5px 10px}.credits small{font-size:8px;color:#aab7a8;margin-left:5px}.wave-alert{position:absolute;right:18px;top:112px;background:#a74d31;color:#fff4db;padding:6px 10px;font:10px 'DM Mono',monospace;letter-spacing:.7px;animation:pulse 1s infinite}@keyframes pulse{50%{opacity:.55}}.deploy-bar{position:absolute;bottom:16px;left:50%;transform:translateX(-50%);width:min(630px,85%);display:flex;justify-content:center;gap:8px}.deploy-card{position:relative;min-width:100px;max-width:150px;flex:1;background:#172122ed;border:1px solid #66756d;color:#e4e6d9;padding:7px 8px 8px;text-align:left;cursor:pointer;transition:.15s}.deploy-card:hover,.deploy-card.selected{border-color:var(--orange);background:#26302d}.deploy-card.selected{box-shadow:0 0 0 1px var(--orange),0 0 14px #e8794240}.deploy-card.disabled{opacity:.46;filter:grayscale(.4)}.card-icon{position:absolute;left:8px;top:8px;width:27px;height:27px;display:grid;place-items:center;background:#34403b;font-size:18px}.card-name{display:block;margin-left:34px;font:800 12px 'Barlow Condensed',sans-serif;letter-spacing:.4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.card-role{display:block;margin:2px 0 7px 34px;color:#9baaa0;font:8px 'DM Mono',monospace}.card-cost{display:flex;justify-content:space-between;border-top:1px solid #79847a44;padding-top:5px;font:9px 'DM Mono',monospace;color:var(--lime)}.card-cost span:last-child{color:#cf8b65}.tipline{position:absolute;bottom:88px;left:50%;transform:translateX(-50%);white-space:nowrap;background:#111a1ce8;padding:5px 9px;color:#bdc7ba;font:8px 'DM Mono',monospace;letter-spacing:.4px}.tipline span{color:var(--orange)}.toast{position:absolute;z-index:5;left:50%;top:22%;transform:translateX(-50%);background:#16201e;border:1px solid var(--orange);padding:10px 18px;font:11px 'DM Mono',monospace;box-shadow:0 5px 20px #0009;white-space:nowrap}.footer{height:35px;display:flex;justify-content:space-between;align-items:end;color:#798680;font:9px 'DM Mono',monospace;letter-spacing:.6px}.footer b{color:#9ba79e;font-weight:500}.footer span:first-child:first-letter{color:var(--orange)}
@media(max-width:650px){body{padding:10px}.topbar{height:49px;padding:0 3px 10px}.header-right{gap:9px}.chapter-label{padding-left:9px;font-size:8px}.status-pill{font-size:8px}.brand b{font-size:15px}.game-frame{aspect-ratio:4/3}.title-screen{left:3%;top:45%;padding:12px}.title-screen h1{font-size:clamp(39px,10vw,62px);margin:14px 0 11px}.title-screen p{font-size:11px;max-width:300px;margin-bottom:13px}.title-stamp{right:-70px;top:0;width:54px;height:54px;font-size:8px}.primary-btn{min-height:38px;padding:0 13px;font-size:11px}.save-note{font-size:7px}.panel-screen{padding:17px 18px}.briefing h2,.recruit-screen h2,.game-over h2,.victory h2{font-size:32px}.briefing p,.recruit-screen p,.game-over p,.victory p{font-size:10px;margin-bottom:12px}.brief-stats{margin:10px 0 14px;padding:9px 0}.brief-stats small{font-size:7px}.brief-stats b{font-size:10px}.mission-hud{top:8px;left:8px;gap:5px;padding:5px}.mission-icon{width:23px;height:23px}.mission-hud small{font-size:7px}.mission-hud b{font-size:10px}.route-track{top:12px;width:24%;left:54%}.route-track-label{font-size:7px}.pause-btn{top:7px;right:8px;width:28px;height:27px}.carrier-health{top:47px;right:8px;width:116px;padding:5px 6px}.health-title{font-size:7px}.credits{left:8px;bottom:85px;font-size:13px;padding:4px 7px}.credits small{font-size:6px}.deploy-bar{bottom:8px;width:96%;gap:3px}.deploy-card{padding:5px 4px;min-width:0}.card-icon{width:22px;height:22px;left:5px;top:6px;font-size:15px}.card-name{font-size:10px;margin-left:26px}.card-role{font-size:6px;margin-left:26px;margin-bottom:5px}.card-cost{font-size:7px}.tipline{bottom:67px;font-size:6px}.wave-alert{top:82px;right:8px;font-size:8px}.footer{font-size:7px}.toast{font-size:9px}.recruit-card{padding:10px}.recruit-avatar{width:52px;height:52px;font-size:25px}}
@media(max-width:390px){.status-pill{display:none}.eyebrow{font-size:8px}.brief-stats span{padding-left:7px}.brief-stats b{font-size:9px}.title-bottom{gap:8px}.save-note{font-size:6px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 960, H = 540, groundY = 409;
  const $ = id => document.getElementById(id);
  const screens = ['titleScreen','briefing','recruitScreen','gameOver','victory'];
  const missions = [
    {name:'THE OLD HIGHWAY',code:'ROUTE 01',entity:'SCP-173',threat:'LOW',desc:'Escort the carrier through the quarantine zone. Deploy agents to stop the anomalies from reaching the vehicle.'},
    {name:'DUST & STATIC',code:'ROUTE 02',entity:'SCP-049',threat:'MODERATE',desc:'A dead signal is broadcasting from the service road. Expect infected personnel and a hostile field medic.'},
    {name:'THE RED MILE',code:'ROUTE 03',entity:'SCP-096',threat:'HIGH',desc:'Keep eyes on the road and stay together. The next extraction point is beyond the old checkpoint.'},
    {name:'NIGHT SHIFT',code:'ROUTE 04',entity:'SCP-106',threat:'SEVERE',desc:'The highway ends at Site-19. One last containment push stands between the team and safety.'}
  ];
  const units = {
    agent:{name:'RIFLEMAN',role:'FIELD AGENT',icon:'◈',cost:50,hp:100,damage:16,range:245,speed:14,rate:1.05,color:'#667b61',kind:'shoot'},
    heavy:{name:'BREACHER',role:'HEAVY SUPPORT',icon:'▣',cost:90,hp:180,damage:32,range:205,speed:9,rate:1.45,color:'#89684e',kind:'shoot'},
    scout:{name:'SCOUT',role:'RAPID RESPONSE',icon:'⌁',cost:70,hp:80,damage:12,range:170,speed:28,rate:.65,color:'#7884a0',kind:'shoot'},
    'scp999':{name:'SCP-999',role:'CONTAINED ALLY',icon:'●',cost:110,hp:230,damage:26,range:58,speed:23,rate:.75,color:'#e6a544',kind:'melee'},
    'scp131':{name:'SCP-131',role:'EYE-POD PAIR',icon:'◉',cost:80,hp:125,damage:14,range:42,speed:25,rate:.7,color:'#8ec2af',kind:'melee'},
    'scp073':{name:'SCP-073',role:'CAIN / ALLY',icon:'♟',cost:135,hp:260,damage:38,range:52,speed:17,rate:1.0,color:'#91a38e',kind:'melee'}
  };
  const recruitPool = ['scp999','scp131','scp073'];
  const defaultRoster = ['agent','heavy','scout'];
  let save = loadSave();
  let state = 'title', missionIndex = Math.max(0,Math.min(missions.length-1,save.mission||0));
  let roster = [...new Set([...(save.roster||[]),...defaultRoster])];
  let credit = save.credit ?? 120, hp = 100, progress = 0, selected = null, gameTime = 0;
  let friendlies = [], hostiles = [], bullets = [], particles = [], props = [], spawnTimer = 0, kills = 0, waveNotified = false;
  let offer = null, lastTimestamp = 0, scenery = 0, shake = 0, toastTimer = 0;
  let paused = false;
  function loadSave(){try{return JSON.parse(localStorage.getItem('lastMileSave'))||{}}catch(_){return {}}}
  function saveGame(){try{localStorage.setItem('lastMileSave',JSON.stringify({mission:missionIndex,roster,credit}))}catch(_){}}
  function setScreen(name){screens.forEach(x=>$(x).classList.toggle('hidden',x!==name));$('shade').style.opacity=name==='titleScreen'?1:(name==='briefing'||name==='recruitScreen'||name==='gameOver'||name==='victory'?'.47':0)}
  function currentMission(){return missions[missionIndex]||missions[0]}
  function showBrief(){const m=currentMission();$('briefCode').textContent=m.code;$('briefTitle').textContent=m.name;$('briefText').textContent=m.desc;$('briefThreat').textContent=m.threat;$('briefEntity').textContent=m.entity;$('chapterLabel').textContent=m.code.replace('ROUTE','OPERATION');setScreen('briefing')}
  $('startBtn').onclick=showBrief;
  $('deployBtn').onclick=beginMission;
  $('retryBtn').onclick=beginMission;
  $('pauseBtn').onclick=()=>{paused=!paused;$('pausePop').classList.toggle('hidden',!paused)};
  $('resumeBtn').onclick=()=>{paused=false;$('pausePop').classList.add('hidden')};
  $('continueBtn').onclick=()=>{if(offer&&!roster.includes(offer)){roster.push(offer);showToast(`${units[offer].name} JOINED THE ROSTER`)}finishMission()};
  $('skipRecruitBtn').onclick=finishMission;
  $('victoryBtn').onclick=()=>{missionIndex=Math.min(missions.length-1,missionIndex+1);credit+=60;saveGame();showBrief()};
  function beginMission(){state='play';paused=false;$('pausePop').classList.add('hidden');$('hud').classList.remove('hidden');setScreen(null);$('hud').classList.remove('hidden');$('missionCode').textContent=currentMission().code+' / DAY';$('missionName').textContent=currentMission().name;friendlies=[];hostiles=[];bullets=[];particles=[];progress=0;hp=100;gameTime=0;kills=0;spawnTimer=1;selected=null;waveNotified=false;credit=Math.max(credit,60);renderCards();updateHud();}
  function renderCards(){const bar=$('deployBar');bar.innerHTML='';roster.forEach(type=>{const u=units[type];if(!u)return;const b=document.createElement('button');b.className='deploy-card';b.dataset.type=type;b.innerHTML=`<span class="card-icon">${u.icon}</span><b class="card-name">${u.name}</b><span class="card-role">${u.role}</span><span class="card-cost"><span>◈ ${u.cost}</span><span>DEPLOY</span></span>`;b.onclick=()=>{if(state!=='play'||paused)return;if(credit<u.cost){showToast('NOT ENOUGH SUPPLIES');return}selected=type;document.querySelectorAll('.deploy-card').forEach(x=>x.classList.toggle('selected',x===b));showToast(`TAP THE ROAD TO DEPLOY ${u.name}`)};bar.appendChild(b)});refreshCardAvailability()}
  function refreshCardAvailability(){document.querySelectorAll('.deploy-card').forEach(b=>b.classList.toggle('disabled',credit<units[b.dataset.type].cost))}
  function deploy(type,x){const u=units[type];if(!u||credit<u.cost)return;credit-=u.cost;const y=groundY-13-Math.random()*13;friendlies.push({type,x:Math.max(215,Math.min(550,x)),y,hp:u.hp,maxHp:u.hp,cd:.2+Math.random()*.5,walk:Math.random()*6,flash:0,alive:true});selected=null;document.querySelectorAll('.deploy-card').forEach(x=>x.classList.remove('selected'));refreshCardAvailability();updateHud();}
  canvas.addEventListener('pointerdown',e=>{if(state!=='play'||paused)return;const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*W/r.width;if(selected){deploy(selected,x);return}if(x>210&&x<W-35)showToast('SELECT AN OPERATIVE BELOW');});
  function spawnEnemy(){const stage=missionIndex;const roll=Math.random();let type='raider';if(stage===0)type=roll<.6?'raider':'173';else if(stage===1)type=roll<.45?'raider':roll<.78?'infected':'049';else if(stage===2)type=roll<.35?'raider':roll<.67?'infected':'096';else type=roll<.3?'raider':roll<.65?'infected':'106';const defs={raider:{name:'ROGUE GUARD',hp:70,speed:15,damage:8,color:'#866650',icon:'!',ranged:true},infected:{name:'INFECTED',hp:95,speed:20,damage:11,color:'#657451',icon:'†',ranged:false},'173':{name:'SCP-173',hp:220,speed:34,damage:22,color:'#b28678',icon:'◉',ranged:false},'049':{name:'SCP-049',hp:200,speed:18,damage:18,color:'#282e30',icon:'♟',ranged:false},'096':{name:'SCP-096',hp:250,speed:38,damage:26,color:'#c4b8a4',icon:'!',ranged:false},'106':{name:'SCP-106',hp:280,speed:13,damage:30,color:'#3b3939',icon:'◉',ranged:true}};const d=defs[type];const scale=1+missionIndex*.24;hostiles.push({type,...d,hp:d.hp*scale,maxHp:d.hp*scale,x:W+20,y:groundY-12-Math.random()*15,cd:.3+Math.random(),walk:Math.random()*7,flash:0,alive:true})}
  function nearestTarget(unit){let best=null,dist=Infinity;hostiles.forEach(e=>{if(!e.alive)return;const d=e.x-unit.x;if(d>=-15&&d<dist){dist=d;best=e}});return best&&dist<=units[unit.type].range?best:null}
  function tick(dt){if(state!=='play'||paused)return;gameTime+=dt;progress=Math.min(1,gameTime/66);scenery+=dt*(26+progress*20);if(shake>0)shake=Math.max(0,shake-dt*20);spawnTimer-=dt;const interval=Math.max(.82,2.4-missionIndex*.24-progress*.6);if(spawnTimer<=0){spawnEnemy();spawnTimer=interval*(.65+Math.random()*.7)}if(progress>.34&&!waveNotified){waveNotified=true;$('waveAlert').classList.remove('hidden');setTimeout(()=>$('waveAlert').classList.add('hidden'),2400)}
